// Verses shown on the home page, one every 20 seconds; the first is 1 Peter 5:7 (same order in every language)
const VERSES = {"ru":[["Все заботы ваши возложите на Него, ибо Он печется о вас.","1 Петра 5:7"],["Он покоит меня на злачных пажитях и водит меня к водам тихим.","Псалом 22:2"],["Небеса проповедуют славу Божию.","Псалом 18:2"],["Не бойся, ибо Я с тобою; не смущайся, ибо Я Бог твой.","Исаия 41:10"],["Претерпевающие Господа обновятся в силе.","Исаия 40:31"],["Дам вам сердце новое и дух новый дам вам.","Иезекииль 36:26"],["Мудрые же будут сиять, как светила на тверди.","Даниил 12:3"],["Блаженны нищие духом, ибо их есть Царство Небесное.","От Матфея 5:3"],["Вы – свет мира.","От Матфея 5:14"],["Не можете служить Богу и маммоне.","От Матфея 6:24"],["Итак идите, научите все народы.","От Матфея 28:19"],["Верующему все возможно.","От Марка 9:23"],["Ныне родился вам в городе Давидовом Спаситель, Который есть Христос Господь.","От Луки 2:11"],["Какою мерою мерите, такою же отмерится и вам.","От Луки 6:38"],["Должно вам родиться свыше.","От Иоанна 3:7"],["Я есмь истинная виноградная лоза, а Отец Мой – виноградарь.","От Иоанна 15:1"],["Более же всего имейте усердную любовь друг ко другу.","1 Петра 4:8"],["Не сообразуйтесь с веком сим, но преобразуйтесь обновлением ума вашего.","Римлянам 12:2"],["Не я живу, но живет во мне Христос.","Галатам 2:20"],["Для меня жизнь – Христос, и смерть – приобретение.","Филиппийцам 1:21"],["И призрел Господь на Авеля и на дар его, а на Каина и на дар его не призрел.","Бытие 4:4-5"],["Господь — крепость моя и слава моя, Он был мне спасением.","Исход 15:2"],["Начало мудрости — страх Господень.","Притчи 1:7"],["Кроткий ответ отвращает гнев, а оскорбительное слово возбуждает ярость.","Притчи 15:1"],["Погибели предшествует гордость, и падению — надменность.","Притчи 16:18"],["И будет после того, излию от Духа Моего на всякую плоть.","Иоиль 2:28"],["Если имеете веру с горчичное зерно и скажете горе сей: «перейди отсюда туда», и она перейдет.","От Матфея 17:20"],["Нет праведного ни одного; нет разумевающего; никто не ищет Бога.","Римлянам 3:10-11"],["Не обманывайтесь: худые общества развращают добрые нравы.","1 Коринфянам 15:33"],["Более же всего имейте усердную любовь друг к другу, потому что любовь покрывает множество грехов.","1 Петра 4:8"],["Тот, Кто в вас, больше того, кто в мире.","1 Иоанна 4:4"],["Покорись Господу и надейся на Него.","Псалом 36:7"],["Защитник сирот и судья вдов Бог во святом Своем жилище.","Псалом 67:6"],["Поищите Господа, и будете живы.","Амос 5:6"],["Господь — Бог ревнитель и мститель; мститель Господь и страшен в гневе.","Наум 1:2"],["Да будет слово ваше: «да, да», «нет, нет»; а что сверх этого, то от лукавого.","От Матфея 5:37"],["У вас же и волосы на голове все сочтены.","От Матфея 10:30"],["Камень, который отвергли строители, соделывался главою угла.","Псалом 117:22"],["Мир велик у любящих закон Твой, и нет им преткновения.","Псалом 118:165"],["Много званых, но мало избранных.","От Матфея 22:14"],["Ибо кто хочет любить жизнь и видеть добрые дни, тот удерживай язык свой от зла.","1 Петра 3:10"],["Ибо время начаться суду с дома Божия.","1 Петра 4:17"],["Готовится мне венец правды, который даст мне Господь, праведный Судия.","2 Тимофею 4:8"],["Поминайте наставников ваших, которые проповедовали вам слово Божие.","Евреям 13:7"],["Смотрите, не отвратитесь и вы от Говорящего.","Евреям 12:25"],["Постигнет ли бедствие город, которого бы не сделал Господь?","Амос 3:6"],["В тот день Я восстановлю скинию Давидову падшую.","Амос 9:11"],["Наставник! мы трудились всю ночь и ничего не поймали, но по слову Твоему закину сеть.","От Луки 5:5"],["Не пришел Я призвать праведников, но грешников к покаянию.","От Луки 5:32"],["От всякого, кому дано много, много и потребуется.","От Луки 12:48"],["Поднимите, врата, верхи ваши, и поднимитесь, двери вечные, и войдет Царь славы!","Псалом 23:7"],["Укажи мне, Господи, пути Твои и научи меня стезям Твоим.","Псалом 24:4"],["Верую, что увижу благость Господню на земле живых.","Псалом 26:13"],["Ты покров мой: Ты охраняешь меня от скорби, окружаешь меня радостями избавления.","Псалом 31:7"],["Малое у праведника лучше богатства многих нечестивых.","Псалом 36:16"],["Милости Господни буду воспевать вечно, в род и род возвещать истину Твою устами моими.","Псалом 88:2"],["Блажен народ, знающий трубный зов! Они ходят во свете лица Твоего, Господи.","Псалом 88:16"],["Говорит Господу: «прибежище мое и защита моя, Бог мой, на Которого я уповаю!»","Псалом 90:2"],["Скажите народам: Господь царствует!","Псалом 95:10"],["Благословите Господа, все Ангелы Его, крепкие силою, исполняющие слово Его.","Псалом 102:20"]],"uk":[["Всяку журбу вашу скинувши на Него, бо Він стараєть ся про вас.","1 Петра 5:7"],["Дав менї оселю серед лугів зелених, він веде мене до тихих потоків.","Псальма 23:2"],["Небо звіщає славу Божу.","Псальма 19:1"],["Не бійся, бо я з тобою; не лякайся, бо я — Бог твій.","Ісаії 41:10"],["Хто на Бога вповає, в того сила відновлюєсь.","Ісаії 40:31"],["І вложу вам нове серце й дам нового духа.","Езекиїла 36:26"],["І розумні сияти муть, неначе сьвітила на небі.","Даниїла 12:3"],["Блаженні вбогі духом, бо їх царство небесне.","Маттея 5:3"],["Ви сьвітло сьвіту.","Маттея 5:14"],["Не можете Богу служити й мамонї.","Маттея 6:24"],["Ійдїть же навчайте всї народи.","Маттея 28:19"],["Все можливе віруючому.","Марка 9:23"],["Бо народивсь вам сьогоднї Спас, що єсть Христос Господь, у городї Давидовому.","Луки 2:11"],["Такою бо мірою, якою міряєте, відміряєть ся вам.","Луки 6:38"],["Мусите ви народити ся звиш.","Йоана 3:7"],["Я правдива виноградина, а Отець мій виноградар.","Йоана 15:1"],["Перш усього ж майте один до одного щиру любов.","1 Петра 4:8"],["І не приладжуйтесь до віку сього, а переображуйтесь обновленнєм ума вашого.","Римлян 12:2"],["Живу ж уже не я, а живе Христос у менї.","Галатів 2:20"],["Бо життє менї Христос, а смерть надбаннє.","Филипян 1:21"],["І споглянув Господь на Абеля і на дар його; на Каїна ж і на його жертву не споглянув.","1 Мойс. 4:4"],["Господь — сила моя й пісня моя, і він став мені спасінням.","2 Мойс. 15:2"],["Почин премудростї — Господень страх.","Приповістей 1:7"],["Відказ лагідний гнїв палкий гасить, а зневажливе слово розбуджує лютість.","Приповістей 15:1"],["Попереду погибелї йде гординя, а поперед упадку — надуте серце.","Приповістей 16:18"],["І буде опісля, що виллю духа мого на всяке тїло.","Йоіла 2:28"],["Коли б ви мали віри з зерно горчицї, то сказали б оцїй горі: Перейди звідсїля туди; то й перейде.","Маттея 17:20"],["Нема праведного нїкого, нема, хто розумів би, нема, хто шукав би Бога.","Римлян 3:10"],["Не обманюйте себе: ледачі бесїди псують добрі звичаї.","1 Коринтян 15:33"],["Перш усього ж майте один до одного щиру любов, бо любов покриває множество гріхів.","1 Петра 4:8"],["Більший Той, хто в вас, нїж той, хто в сьвітї.","1 Йоана 4:4"],["Вповай тихим серцем на Господа, і дожидай його.","Псальма 37:7"],["Отець сиріт і оборонець вдовиць — Бог у сьвятому жилищі своїм.","Псальма 68:5"],["Шукайте ви Господа, а будете жити.","Амоса 5:6"],["Бог ревнивий у помстї; Господь повен помсти й страшний в досадї.","Наума 1:2"],["Слово ж ваше нехай буде: так, так; нї, нї; бо що більш над се, те від лихого.","Маттея 5:37"],["У вас же і все волоссє на голові перелїчене.","Маттея 10:30"],["Камінь, котрого відкинули будівничі, угольним каменем стався.","Псальма 118:22"],["Великим спокоєм радуються ті, що люблять закон твій і нема для них спотикання.","Псальма 119:165"],["Багато званих, мало ж вибраних.","Маттея 22:14"],["Хто бо хоче життє любити, і видїти днї добрі, нехай вдержить язик свій від злого.","1 Петра 3:10"],["Бо пора початись судові від дому Божого.","1 Петра 4:17"],["На останок готовить ся менї вінець правди, котрий оддасть менї Господь того дня, праведний суддя.","2 Тимотея 4:8"],["Поминайте наставників ваших, що глаголали вам слово Боже.","Жидів 13:7"],["Гледїть, щоб не відректись глаголющого.","Жидів 12:25"],["Чи ж складеться в містї лихо без Божої волї?","Амоса 3:6"],["У той день Я відновлю впалу скинію Давидову.","Амоса 9:11"],["Наставниче, всю ніч трудившись, нїчого не піймали ми; тільки ж, по слову Твоєму, закину невода.","Луки 5:5"],["Не прийшов я кликати праведників, а грішників до покаяння.","Луки 5:32"],["Від усякого, кому дано багато, багато вимагати меть ся від него.","Луки 12:48"],["Відчиняйтесь, брами високії, отвирайтесь, ворота вічні, нехай входить царь слави!","Псальма 24:7"],["Господи, вкажи менї дороги твої, і навчи, де стежки твої!","Псальма 25:4"],["Вірую, що побачу благість Господню на землі живих.","Псальма 27:13"],["Ти мій рятунок; спасаєш мене в тїснотї, ти сповняєш мене радостю спасення.","Псальма 32:7"],["Луччий малий достаток праведника, як наддостатки многих беззаконників.","Псальма 37:16"],["Милості Господні буду сьпівати повік, з роду в рід звіщати устами моїми вірність твою.","Псальма 89:1"],["Щасливий нарід, що розуміє голос твій торжествуючий! Господи, при сьвітлї лиця твого вони ходити будуть.","Псальма 89:15"],["Я кажу до Господа: Ти моя пристань і твердиня, мій Бог, на його вповати буду.","Псальма 91:2"],["Звіщайте між народами: Господь царює!","Псальма 96:10"],["Благословіть Господа, ви ангели його, силою потужні, сповнителї слова його!","Псальма 103:20"]],"en":[["Casting all your care upon him; for he careth for you.","1 Peter 5:7"],["He maketh me to lie down in green pastures: he leadeth me beside the still waters.","Psalm 23:2"],["The heavens declare the glory of God.","Psalm 19:1"],["Fear thou not; for I am with thee: be not dismayed; for I am thy God.","Isaiah 41:10"],["They that wait upon the LORD shall renew their strength.","Isaiah 40:31"],["A new heart also will I give you, and a new spirit will I put within you.","Ezekiel 36:26"],["And they that be wise shall shine as the brightness of the firmament.","Daniel 12:3"],["Blessed are the poor in spirit: for theirs is the kingdom of heaven.","Matthew 5:3"],["Ye are the light of the world.","Matthew 5:14"],["Ye cannot serve God and mammon.","Matthew 6:24"],["Go ye therefore, and teach all nations.","Matthew 28:19"],["All things are possible to him that believeth.","Mark 9:23"],["For unto you is born this day in the city of David a Saviour, which is Christ the Lord.","Luke 2:11"],["For with the same measure that ye mete withal it shall be measured to you again.","Luke 6:38"],["Ye must be born again.","John 3:7"],["I am the true vine, and my Father is the husbandman.","John 15:1"],["And above all things have fervent charity among yourselves.","1 Peter 4:8"],["And be not conformed to this world: but be ye transformed by the renewing of your mind.","Romans 12:2"],["Nevertheless I live; yet not I, but Christ liveth in me.","Galatians 2:20"],["For to me to live is Christ, and to die is gain.","Philippians 1:21"],["And the LORD had respect unto Abel and to his offering: But unto Cain and to his offering he had not respect.","Genesis 4:4"],["The LORD is my strength and song, and he is become my salvation.","Exodus 15:2"],["The fear of the LORD is the beginning of knowledge.","Proverbs 1:7"],["A soft answer turneth away wrath: but grievous words stir up anger.","Proverbs 15:1"],["Pride goeth before destruction, and an haughty spirit before a fall.","Proverbs 16:18"],["And it shall come to pass afterward, that I will pour out my spirit upon all flesh.","Joel 2:28"],["If ye have faith as a grain of mustard seed, ye shall say unto this mountain, Remove hence to yonder place; and it shall remove.","Matthew 17:20"],["There is none righteous, no, not one: There is none that understandeth, there is none that seeketh after God.","Romans 3:10"],["Be not deceived: evil communications corrupt good manners.","1 Corinthians 15:33"],["And above all things have fervent charity among yourselves: for charity shall cover the multitude of sins.","1 Peter 4:8"],["Greater is he that is in you, than he that is in the world.","1 John 4:4"],["Rest in the LORD, and wait patiently for him.","Psalm 37:7"],["A father of the fatherless, and a judge of the widows, is God in his holy habitation.","Psalm 68:5"],["Seek the LORD, and ye shall live.","Amos 5:6"],["God is jealous, and the LORD revengeth; the LORD revengeth, and is furious.","Nahum 1:2"],["But let your communication be, Yea, yea; Nay, nay: for whatsoever is more than these cometh of evil.","Matthew 5:37"],["But the very hairs of your head are all numbered.","Matthew 10:30"],["The stone which the builders refused is become the head stone of the corner.","Psalm 118:22"],["Great peace have they which love thy law: and nothing shall offend them.","Psalm 119:165"],["Many are called, but few are chosen.","Matthew 22:14"],["For he that will love life, and see good days, let him refrain his tongue from evil.","1 Peter 3:10"],["For the time is come that judgment must begin at the house of God.","1 Peter 4:17"],["Henceforth there is laid up for me a crown of righteousness, which the Lord, the righteous judge, shall give me at that day.","2 Timothy 4:8"],["Remember them which have the rule over you, who have spoken unto you the word of God.","Hebrews 13:7"],["See that ye refuse not him that speaketh.","Hebrews 12:25"],["Shall there be evil in a city, and the LORD hath not done it?","Amos 3:6"],["In that day will I raise up the tabernacle of David that is fallen.","Amos 9:11"],["Master, we have toiled all the night, and have taken nothing: nevertheless at thy word I will let down the net.","Luke 5:5"],["I came not to call the righteous, but sinners to repentance.","Luke 5:32"],["Unto whomsoever much is given, of him shall be much required.","Luke 12:48"],["Lift up your heads, O ye gates; and be ye lift up, ye everlasting doors; and the King of glory shall come in.","Psalm 24:7"],["Shew me thy ways, O LORD; teach me thy paths.","Psalm 25:4"],["I believe that I shall see the goodness of the LORD in the land of the living.","Psalm 27:13"],["Thou art my hiding place; thou shalt preserve me from trouble; thou shalt compass me about with songs of deliverance.","Psalm 32:7"],["A little that a righteous man hath is better than the riches of many wicked.","Psalm 37:16"],["I will sing of the mercies of the LORD for ever: with my mouth will I make known thy faithfulness to all generations.","Psalm 89:1"],["Blessed is the people that know the joyful sound: they shall walk, O LORD, in the light of thy countenance.","Psalm 89:15"],["I will say of the LORD, He is my refuge and my fortress: my God; in him will I trust.","Psalm 91:2"],["Say among the heathen that the LORD reigneth.","Psalm 96:10"],["Bless the LORD, ye his angels, that excel in strength, that do his commandments.","Psalm 103:20"]],"de":[["Alle Sorge werfet auf ihn; denn er sorgt für euch.","1. Petrus 5:7"],["Er weidet mich auf grüner Aue und führet mich zum frischen Wasser.","Psalm 23:2"],["Die Himmel erzählen die Ehre Gottes.","Psalm 19:2"],["Fürchte dich nicht, ich bin mit dir; weiche nicht, denn ich bin dein Gott.","Jesaja 41:10"],["Die auf den HERRN harren, kriegen neue Kraft.","Jesaja 40:31"],["Und ich will euch ein neues Herz und einen neuen Geist in euch geben.","Hesekiel 36:26"],["Die Lehrer aber werden leuchten wie des Himmels Glanz.","Daniel 12:3"],["Selig sind, die da geistlich arm sind; denn das Himmelreich ist ihr.","Matthäus 5:3"],["Ihr seid das Licht der Welt.","Matthäus 5:14"],["Ihr könnt nicht Gott dienen und dem Mammon.","Matthäus 6:24"],["Darum gehet hin und lehret alle Völker.","Matthäus 28:19"],["Alle Dinge sind möglich dem, der da glaubt.","Markus 9:23"],["Denn euch ist heute der Heiland geboren, welcher ist Christus, der HERR, in der Stadt Davids.","Lukas 2:11"],["Denn eben mit dem Maß, mit dem ihr messet, wird man euch wieder messen.","Lukas 6:38"],["Ihr müsset von neuem geboren werden.","Johannes 3:7"],["Ich bin der rechte Weinstock, und mein Vater der Weingärtner.","Johannes 15:1"],["Vor allen Dingen aber habt untereinander eine inbrünstige Liebe.","1. Petrus 4:8"],["Und stellet euch nicht dieser Welt gleich, sondern verändert euch durch die Erneuerung eures Sinnes.","Römer 12:2"],["Ich lebe aber; doch nun nicht ich, sondern Christus lebt in mir.","Galater 2:20"],["Denn Christus ist mein Leben, und Sterben ist mein Gewinn.","Philipper 1:21"],["Und der HERR sah gnädig an Abel und sein Opfer; aber Kain und sein Opfer sah er nicht gnädig an.","1. Mose 4:4"],["Der HERR ist meine Stärke und mein Lobgesang und ist mein Heil.","2. Mose 15:2"],["Des HERRN Furcht ist Anfang der Erkenntnis.","Sprüche 1:7"],["Eine linde Antwort stillt den Zorn; aber ein hartes Wort richtet Grimm an.","Sprüche 15:1"],["Wer zu Grunde gehen soll, der wird zuvor stolz; und Hochmut kommt vor dem Fall.","Sprüche 16:18"],["Und nach diesem will ich meinen Geist ausgießen über alles Fleisch.","Joel 3:1"],["So ihr Glauben habt wie ein Senfkorn, so mögt ihr sagen zu diesem Berge: Hebe dich von hinnen dorthin! so wird er sich heben.","Matthäus 17:20"],["Da ist nicht, der gerecht sei, auch nicht einer. Da ist nicht, der verständig sei; da ist nicht, der nach Gott frage.","Römer 3:10"],["Lasset euch nicht verführen! Böse Geschwätze verderben gute Sitten.","1. Korinther 15:33"],["Vor allen Dingen aber habt untereinander eine inbrünstige Liebe; denn die Liebe deckt auch der Sünden Menge.","1. Petrus 4:8"],["Der in euch ist, ist größer, als der in der Welt ist.","1. Johannes 4:4"],["Sei stille dem HERRN und warte auf ihn.","Psalm 37:7"],["Der ein Vater ist der Waisen und ein Richter der Witwen, Gott in seiner heiligen Wohnung.","Psalm 68:6"],["Suchet den HERRN, so werdet ihr leben!","Amos 5:6"],["Der HERR ist ein eifriger Gott und ein Rächer, ja, ein Rächer ist der HERR und zornig.","Nahum 1:2"],["Eure Rede aber sei: Ja, ja; nein, nein. Was darüber ist, das ist vom Übel.","Matthäus 5:37"],["Nun aber sind auch eure Haare auf dem Haupte alle gezählt.","Matthäus 10:30"],["Der Stein, den die Bauleute verworfen haben, ist zum Eckstein geworden.","Psalm 118:22"],["Großen Frieden haben, die dein Gesetz lieben; sie werden nicht straucheln.","Psalm 119:165"],["Viele sind berufen, aber wenige sind auserwählt.","Matthäus 22:14"],["Denn wer leben will und gute Tage sehen, der schweige seine Zunge, daß sie nichts Böses rede.","1. Petrus 3:10"],["Denn es ist Zeit, daß anfange das Gericht an dem Hause Gottes.","1. Petrus 4:17"],["Hinfort ist mir beigelegt die Krone der Gerechtigkeit, welche mir der HERR an jenem Tage, der gerechte Richter, geben wird.","2. Timotheus 4:8"],["Gedenkt an eure Lehrer, die euch das Wort Gottes gesagt haben.","Hebräer 13:7"],["Sehet zu, daß ihr den nicht abweiset, der da redet.","Hebräer 12:25"],["Ist auch ein Unglück in der Stadt, daß der HERR nicht tue?","Amos 3:6"],["Zur selben Zeit will ich die zerfallene Hütte Davids wieder aufrichten.","Amos 9:11"],["Meister, wir haben die ganze Nacht gearbeitet und nichts gefangen, aber auf dein Wort will ich das Netz auswerfen.","Lukas 5:5"],["Ich bin nicht gekommen, die Gerechten zu rufen, sondern die Sünder zur Buße.","Lukas 5:32"],["Welchem viel gegeben ist, bei dem wird man viel suchen.","Lukas 12:48"],["Machet die Tore weit und die Türen in der Welt hoch, daß der König der Ehren einziehe!","Psalm 24:7"],["HERR, zeige mir deine Wege und lehre mich deine Steige.","Psalm 25:4"],["Ich glaube aber doch, daß ich sehen werde das Gute des HERRN im Lande der Lebendigen.","Psalm 27:13"],["Du bist mein Schirm; du wirst mich vor Angst behüten, daß ich errettet gar fröhlich rühmen kann.","Psalm 32:7"],["Das wenige, das ein Gerechter hat, ist besser als das große Gut vieler Gottlosen.","Psalm 37:16"],["Ich will singen von der Gnade des HERRN ewiglich und seine Wahrheit verkündigen mit meinem Munde für und für.","Psalm 89:2"],["Wohl dem Volk, das jauchzen kann! HERR, sie werden im Licht deines Antlitzes wandeln.","Psalm 89:16"],["Der spricht zu dem HERRN: Meine Zuversicht und meine Burg, mein Gott, auf den ich hoffe.","Psalm 91:2"],["Saget unter den Heiden, daß der HERR König sei!","Psalm 96:10"],["Lobet den HERRN, ihr seine Engel, ihr starken Helden, die ihr seine Befehle ausrichtet.","Psalm 103:20"]],"es":[["Echando toda vuestra solicitud en él, porque él tiene cuidado de vosotros.","1 Pedro 5:7"],["En lugares de delicados pastos me hará yacer: junto á aguas de reposo me pastoreará.","Salmo 23:2"],["Los cielos cuentan la gloria de Dios.","Salmo 19:1"],["No temas, que yo soy contigo; no desmayes, que yo soy tu Dios.","Isaías 41:10"],["Los que esperan á Jehová tendrán nuevas fuerzas.","Isaías 40:31"],["Y os daré corazón nuevo, y pondré espíritu nuevo dentro de vosotros.","Ezequiel 36:26"],["Y los entendidos resplandecerán como el resplandor del firmamento.","Daniel 12:3"],["Bienaventurados los pobres en espíritu: porque de ellos es el reino de los cielos.","Mateo 5:3"],["Vosotros sois la luz del mundo.","Mateo 5:14"],["No podéis servir á Dios y á Mammón.","Mateo 6:24"],["Por tanto, id, y doctrinad á todos los Gentiles.","Mateo 28:19"],["Al que cree todo es posible.","Marcos 9:23"],["Que os ha nacido hoy, en la ciudad de David, un Salvador, que es CRISTO el Señor.","Lucas 2:11"],["Porque con la misma medida que midiereis, os será vuelto á medir.","Lucas 6:38"],["Os es necesario nacer otra vez.","Juan 3:7"],["Yo soy la vid verdadera, y mi Padre es el labrador.","Juan 15:1"],["Y sobre todo, tened entre vosotros ferviente caridad.","1 Pedro 4:8"],["Y no os conforméis á este siglo; mas reformaos por la renovación de vuestro entendimiento.","Romanos 12:2"],["Vivo, no ya yo, mas vive Cristo en mí.","Gálatas 2:20"],["Porque para mí el vivir es Cristo, y el morir es ganancia.","Filipenses 1:21"],["Y miró Jehová con agrado á Abel y á su ofrenda; mas no miró propicio á Caín y á la ofrenda suya.","Génesis 4:4"],["Jehová es mi fortaleza, y mi canción, y hame sido por salud.","Éxodo 15:2"],["El principio de la sabiduría es el temor de Jehová.","Proverbios 1:7"],["La blanda respuesta quita la ira: mas la palabra áspera hace subir el furor.","Proverbios 15:1"],["Antes del quebrantamiento es la soberbia; y antes de la caída la altivez de espíritu.","Proverbios 16:18"],["Y será que después de esto derramaré mi espíritu sobre toda carne.","Joel 2:28"],["Si tuviereis fe como un grano de mostaza, diréis á este monte: Pásate de aquí allá: y se pasará.","Mateo 17:20"],["No hay justo, ni aun uno; no hay quien entienda, no hay quien busque á Dios.","Romanos 3:10"],["No erréis: las malas conversaciones corrompen las buenas costumbres.","1 Corintios 15:33"],["Y sobre todo, tened entre vosotros ferviente caridad; porque la caridad cubrirá multitud de pecados.","1 Pedro 4:8"],["El que en vosotros está, es mayor que el que está en el mundo.","1 Juan 4:4"],["Calla á Jehová, y espera en él.","Salmo 37:7"],["Padre de huérfanos y defensor de viudas es Dios en su santa morada.","Salmo 68:5"],["Buscad á Jehová, y vivid.","Amós 5:6"],["Dios celoso y vengador es Jehová; vengador es Jehová, y Señor de ira.","Nahum 1:2"],["Mas sea vuestro hablar: Sí, sí; No, no; porque lo que es más de esto, de mal procede.","Mateo 5:37"],["Pues aun vuestros cabellos están todos contados.","Mateo 10:30"],["La piedra que desecharon los edificadores, ha venido á ser cabeza del ángulo.","Salmo 118:22"],["Mucha paz tienen los que aman tu ley; y no hay para ellos tropiezo.","Salmo 119:165"],["Muchos son llamados, y pocos escogidos.","Mateo 22:14"],["Porque el que quiere amar la vida, y ver días buenos, refrene su lengua de mal.","1 Pedro 3:10"],["Porque es tiempo de que el juicio comience de la casa de Dios.","1 Pedro 4:17"],["Por lo demás, me está guardada la corona de justicia, la cual me dará el Señor, juez justo, en aquel día.","2 Timoteo 4:8"],["Acordaos de vuestros pastores, que os hablaron la palabra de Dios.","Hebreos 13:7"],["Mirad que no desechéis al que habla.","Hebreos 12:25"],["¿Habrá algún mal en la ciudad, el cual Jehová no haya hecho?","Amós 3:6"],["En aquel día yo levantaré el tabernáculo de David, caído.","Amós 9:11"],["Maestro, habiendo trabajado toda la noche, nada hemos tomado; mas en tu palabra echaré la red.","Lucas 5:5"],["No he venido á llamar justos, sino pecadores á arrepentimiento.","Lucas 5:32"],["A cualquiera que fué dado mucho, mucho será vuelto á demandar de él.","Lucas 12:48"],["Alzad, oh puertas, vuestras cabezas, y alzaos vosotras, puertas eternas, y entrará el Rey de gloria.","Salmo 24:7"],["Muéstrame, oh Jehová, tus caminos; enséñame tus sendas.","Salmo 25:4"],["Creo que veré la bondad de Jehová en la tierra de los vivientes.","Salmo 27:13"],["Tú eres mi refugio; me guardarás de angustia; con cánticos de liberación me rodearás.","Salmo 32:7"],["Mejor es lo poco del justo, que las riquezas de muchos pecadores.","Salmo 37:16"],["Las misericordias de Jehová cantaré perpetuamente; de generación en generación haré notoria tu verdad con mi boca.","Salmo 89:1"],["Bienaventurado el pueblo que sabe aclamarte: andarán, oh Jehová, á la luz de tu rostro.","Salmo 89:15"],["Diré yo á Jehová: Esperanza mía, y castillo mío; mi Dios, en él confiaré.","Salmo 91:2"],["Decid en las gentes: Jehová reinó.","Salmo 96:10"],["Bendecid á Jehová, vosotros sus ángeles, poderosos en fortaleza, que ejecutáis su palabra.","Salmo 103:20"]],"fr":[["Vous déchargeant sur lui de tous vos soucis, parce qu'il a soin de vous.","1 Pierre 5:7"],["Il me fait reposer dans des pâturages herbeux; il me mène le long des eaux tranquilles.","Psaume 23:2"],["Les cieux racontent la gloire de Dieu.","Psaume 19:2"],["Ne crains point, car je suis avec toi; ne sois point éperdu, car je suis ton Dieu!","Ésaïe 41:10"],["Ceux qui s'attendent à l'Éternel reprennent de nouvelles forces.","Ésaïe 40:31"],["Je vous donnerai un cœur nouveau, et je mettrai en vous un esprit nouveau.","Ézéchiel 36:26"],["Ceux qui auront été intelligents brilleront comme la splendeur de l'étendue.","Daniel 12:3"],["Heureux les pauvres en esprit; car le royaume des cieux est à eux.","Matthieu 5:3"],["Vous êtes la lumière du monde.","Matthieu 5:14"],["Vous ne pouvez servir Dieu et Mammon.","Matthieu 6:24"],["Allez donc et instruisez toutes les nations.","Matthieu 28:19"],["Toutes choses sont possibles pour celui qui croit.","Marc 9:23"],["C'est qu'aujourd'hui, dans la ville de David, un Sauveur, qui est le Christ, le Seigneur, vous est né.","Luc 2:11"],["Car on vous mesurera de la mesure dont vous vous servez envers les autres.","Luc 6:38"],["Il faut que vous naissiez de nouveau.","Jean 3:7"],["Je suis le vrai cep, et mon Père est le vigneron.","Jean 15:1"],["Surtout ayez les uns pour les autres une ardente charité.","1 Pierre 4:8"],["Et ne vous conformez point au présent siècle, mais soyez transformés par le renouvellement de votre esprit.","Romains 12:2"],["Si je vis, ce n'est plus moi, mais c'est Christ qui vit en moi.","Galates 2:20"],["Car pour moi Christ est ma vie, et la mort m'est un gain.","Philippiens 1:21"],["Et l'Éternel eut égard à Abel, et à son oblation; mais il n'eut point égard à Caïn, ni à son oblation.","Genèse 4:4"],["L'Éternel est ma force et ma louange: il a été mon libérateur.","Exode 15:2"],["La crainte de l'Éternel est le principal point de la science.","Proverbes 1:7"],["Une réponse douce apaise la fureur; mais la parole dure excite la colère.","Proverbes 15:1"],["L'orgueil va devant l'écrasement, et la fierté d'esprit devant la ruine.","Proverbes 16:18"],["Après cela, je répandrai mon esprit sur toute chair.","Joël 3:1"],["Si vous aviez de la foi comme un grain de moutarde, vous diriez à cette montagne: Transporte-toi d'ici là, et elle s'y transporterait.","Matthieu 17:20"],["Il n'y a point de juste, non pas même un seul. Il n'y a personne qui ait de l'intelligence; il n'y en a point qui cherche Dieu.","Romains 3:10"],["Ne vous abusez point: les mauvaises compagnies corrompent les bonnes mœurs.","1 Corinthiens 15:33"],["Surtout ayez les uns pour les autres une ardente charité; car la charité couvrira une multitude de péchés.","1 Pierre 4:8"],["Celui qui est en vous, est plus grand que celui qui est dans le monde.","1 Jean 4:4"],["Demeure tranquille en regardant à l'Éternel, et t'attends à lui.","Psaume 37:7"],["Le père des orphelins et le défenseur des veuves, c'est Dieu, dans sa demeure sainte.","Psaume 68:6"],["Cherchez l'Éternel, et vous vivrez.","Amos 5:6"],["L'Éternel est un Dieu jaloux et vengeur; l'Éternel est vengeur, et il a la fureur à son commandement.","Nahum 1:2"],["Mais que votre parole soit: Oui, oui, Non, non; ce qu'on dit de plus, vient du Malin.","Matthieu 5:37"],["Les cheveux même de votre tête sont tous comptés.","Matthieu 10:30"],["La pierre que ceux qui bâtissaient ont rejetée, est devenue la principale de l'angle.","Psaume 118:22"],["Il y a une grande paix pour ceux qui aiment ta loi, et rien ne peut les renverser.","Psaume 119:165"],["Il y a beaucoup d'appelés, mais peu d'élus.","Matthieu 22:14"],["En effet, que celui qui veut aimer la vie et voir des jours heureux, garde sa langue du mal.","1 Pierre 3:10"],["Car le temps vient où le jugement doit commencer par la maison de Dieu.","1 Pierre 4:17"],["Au reste, la couronne de justice m'est réservée, le Seigneur, le juste juge, me la donnera en ce jour-là.","2 Timothée 4:8"],["Souvenez-vous de vos conducteurs, qui vous ont annoncé la parole de Dieu.","Hébreux 13:7"],["Prenez garde de ne pas mépriser celui qui vous parle.","Hébreux 12:25"],["Et s'il arrive un malheur dans une ville, n'est-ce pas l'Éternel qui l'a fait?","Amos 3:6"],["En ce temps-là, je relèverai le tabernacle de David qui est tombé.","Amos 9:11"],["Maître, nous avons travaillé toute la nuit sans rien prendre; toutefois, sur ta parole, je jetterai le filet.","Luc 5:5"],["Je ne suis pas venu appeler à la repentance les justes, mais les pécheurs.","Luc 5:32"],["Il sera beaucoup redemandé à quiconque il aura été beaucoup donné.","Luc 12:48"],["Portes, élevez vos linteaux! Haussez-vous, portes éternelles, et le roi de gloire entrera.","Psaume 24:7"],["Éternel, fais-moi connaître tes voies, enseigne-moi tes sentiers!","Psaume 25:4"],["Je crois que je verrai les biens de l'Éternel dans la terre des vivants.","Psaume 27:13"],["Tu es ma retraite; tu me garantis de la détresse, tu m'environnes de chants de délivrance.","Psaume 32:7"],["Mieux vaut le peu du juste que l'abondance de plusieurs méchants.","Psaume 37:16"],["Je chanterai à jamais les bontés de l'Éternel; ma bouche publiera ta fidélité d'âge en âge.","Psaume 89:2"],["Heureux le peuple qui connaît les cris de joie! Éternel, ils marchent à la clarté de ta face.","Psaume 89:16"],["Je dis à l'Éternel: Mon refuge et ma forteresse! mon Dieu en qui je m'assure!","Psaume 91:2"],["Dites parmi les nations: L'Éternel règne!","Psaume 96:10"],["Bénissez l'Éternel, vous ses anges puissants en force, qui exécutez son commandement!","Psaume 103:20"]],"it":[["Gettando su lui ogni vostra sollecitudine, perch'Egli ha cura di voi.","1 Pietro 5:7"],["Egli mi fa giacere in verdeggianti paschi, mi guida lungo le acque chete.","Salmo 23:2"],["I cieli raccontano la gloria di Dio.","Salmo 19:1"],["Non temere, perché io son teco; non ti smarrire, perché io sono il tuo Dio.","Isaia 41:10"],["Quelli che sperano nell'Eterno acquistan nuove forze.","Isaia 40:31"],["E vi darò un cuor nuovo, e metterò dentro di voi uno spirito nuovo.","Ezechiele 36:26"],["E i savi risplenderanno come lo splendore della distesa.","Daniele 12:3"],["Beati i poveri in ispirito, perché di loro è il regno de' cieli.","Matteo 5:3"],["Voi siete la luce del mondo.","Matteo 5:14"],["Voi non potete servire a Dio ed a Mammona.","Matteo 6:24"],["Andate dunque, ammaestrate tutti i popoli.","Matteo 28:19"],["Ogni cosa è possibile a chi crede.","Marco 9:23"],["Oggi, nella città di Davide, v'è nato un Salvatore, che è Cristo, il Signore.","Luca 2:11"],["Perché con la misura onde misurate, sarà rimisurato a voi.","Luca 6:38"],["Bisogna che nasciate di nuovo.","Giovanni 3:7"],["Io sono la vera vite, e il Padre mio è il vignaiuolo.","Giovanni 15:1"],["Soprattutto, abbiate amore intenso gli uni per gli altri.","1 Pietro 4:8"],["E non vi conformate a questo secolo, ma siate trasformati mediante il rinnovamento della vostra mente.","Romani 12:2"],["Non son più io che vivo, ma è Cristo che vive in me.","Galati 2:20"],["Poiché per me il vivere è Cristo, e il morire guadagno.","Filippesi 1:21"],["E l'Eterno guardò con favore Abele e la sua offerta, ma non guardò con favore Caino e l'offerta sua.","Genesi 4:4"],["L'Eterno è la mia forza e l'oggetto del mio cantico; egli è stato la mia salvezza.","Esodo 15:2"],["Il timore dell'Eterno è il principio della scienza.","Proverbi 1:7"],["La risposta dolce calma il furore, ma la parola dura eccita l'ira.","Proverbi 15:1"],["La superbia precede la rovina, e l'alterezza dello spirito precede la caduta.","Proverbi 16:18"],["Dopo questo, io spanderò il mio spirito sopra ogni carne.","Gioele 2:28"],["Se avete fede quanto un granel di senapa, potrete dire a questo monte: Passa di qua là, e passerà.","Matteo 17:20"],["Non v'è alcun giusto, neppur uno. Non v'è alcuno che abbia intendimento, non v'è alcuno che ricerchi Dio.","Romani 3:10"],["Non v'ingannate: le cattive compagnie corrompono i buoni costumi.","1 Corinzi 15:33"],["Soprattutto, abbiate amore intenso gli uni per gli altri, perché l'amore copre moltitudine di peccati.","1 Pietro 4:8"],["Colui che è in voi è più grande di colui che è nel mondo.","1 Giovanni 4:4"],["Sta in silenzio dinanzi all'Eterno, e aspettalo.","Salmo 37:7"],["Padre degli orfani e difensore delle vedove è Dio nella sua santa dimora.","Salmo 68:5"],["Cercate l'Eterno e vivrete.","Amos 5:6"],["L'Eterno è un Dio geloso e vendicatore; L'Eterno è vendicatore e pieno di furore.","Nahum 1:2"],["Ma sia il vostro parlare: Sì, sì; no, no; poiché il di più vien dal maligno.","Matteo 5:37"],["Ma quant'è a voi, perfino i capelli del vostro capo son tutti contati.","Matteo 10:30"],["La pietra che gli edificatori avevano rigettata è divenuta la pietra angolare.","Salmo 118:22"],["Gran pace hanno quelli che amano la tua legge, e non c'è nulla che possa farli cadere.","Salmo 119:165"],["Molti son chiamati, ma pochi eletti.","Matteo 22:14"],["Perché chi vuol amar la vita e veder buoni giorni, rattenga la sua lingua dal male.","1 Pietro 3:10"],["Poiché è giunto il tempo in cui il giudicio ha da cominciare dalla casa di Dio.","1 Pietro 4:17"],["Del rimanente mi è riservata la corona di giustizia che il Signore, il giusto giudice, mi assegnerà in quel giorno.","2 Timoteo 4:8"],["Ricordatevi dei vostri conduttori, i quali v'hanno annunziato la parola di Dio.","Ebrei 13:7"],["Guardate di non rifiutare Colui che parla.","Ebrei 12:25"],["Una sciagura piomba ella sopra una città, senza che l'Eterno ne sia l'autore?","Amos 3:6"],["In quel giorno, io rialzerò la capanna di Davide ch'è caduta.","Amos 9:11"],["Maestro, tutta la notte ci siamo affaticati, e non abbiam preso nulla; però, alla tua parola, calerò le reti.","Luca 5:5"],["Io non son venuto a chiamare de' giusti, ma de' peccatori a ravvedimento.","Luca 5:32"],["A chi molto è stato dato, molto sarà ridomandato.","Luca 12:48"],["O porte, alzate i vostri capi; e voi, porte eterne, alzatevi; e il Re di gloria entrerà.","Salmo 24:7"],["O Eterno, fammi conoscere le tue vie, insegnami i tuoi sentieri.","Salmo 25:4"],["Io credo che vedrò la bontà dell'Eterno sulla terra de' viventi.","Salmo 27:13"],["Tu sei il mio ricetto, tu mi guarderai da distretta, tu mi circonderai di canti di liberazione.","Salmo 32:7"],["Meglio vale il poco del giusto che l'abbondanza di molti empi.","Salmo 37:16"],["Io canterò in perpetuo le benignità dell'Eterno; con la mia bocca farò conoscere la tua fedeltà di età in età.","Salmo 89:1"],["Beato il popolo che conosce il grido di giubilo; esso cammina, o Eterno, alla luce del tuo volto.","Salmo 89:15"],["Io dico all'Eterno: Tu sei il mio rifugio e la mia fortezza, il mio Dio, in cui confido!","Salmo 91:2"],["Dite fra le nazioni: L'Eterno regna!","Salmo 96:10"],["Benedite l'Eterno, voi suoi angeli, potenti e forti, che fate ciò ch'egli dice!","Salmo 103:20"]],"pt":[["Lançando sobre ele toda a vossa ansiedade, porque ele tem cuidado de vós.","1 Pedro 5:7"],["Deitar-me faz em pastos verdejantes; guia-me mansamente a águas tranqüilas.","Salmo 23:2"],["Os céus proclamam a glória de Deus.","Salmo 19:1"],["Não temas, porque eu sou contigo; não te assombres, porque eu sou teu Deus.","Isaías 41:10"],["Os que esperam no Senhor renovarão as suas forças.","Isaías 40:31"],["Também vos darei um coração novo, e porei dentro de vós um espírito novo.","Ezequiel 36:26"],["Os que forem sábios, pois, resplandecerão como o fulgor do firmamento.","Daniel 12:3"],["Bem-aventurados os humildes de espírito, porque deles é o reino dos céus.","Mateus 5:3"],["Vós sois a luz do mundo.","Mateus 5:14"],["Não podeis servir a Deus e às riquezas.","Mateus 6:24"],["Portanto ide, fazei discípulos de todas as nações.","Mateus 28:19"],["Tudo é possível ao que crê.","Marcos 9:23"],["É que vos nasceu hoje, na cidade de Davi, o Salvador, que é Cristo, o Senhor.","Lucas 2:11"],["Porque com a mesma medida com que medis, vos medirão a vós.","Lucas 6:38"],["Necessário vos é nascer de novo.","João 3:7"],["Eu sou a videira verdadeira, e meu Pai é o viticultor.","João 15:1"],["Tende antes de tudo ardente amor uns para com os outros.","1 Pedro 4:8"],["E não vos conformeis a este mundo, mas transformai-vos pela renovação da vossa mente.","Romanos 12:2"],["Vivo, não mais eu, mas Cristo vive em mim.","Gálatas 2:20"],["Porque para mim o viver é Cristo, e o morrer é lucro.","Filipenses 1:21"],["Atentou o Senhor para Abel e para a sua oferta, mas para Caim e para a sua oferta não atentou.","Gênesis 4:4"],["O Senhor é a minha força, e o meu cântico; ele se tem tornado a minha salvação.","Êxodo 15:2"],["O temor do Senhor é o princípio do conhecimento.","Provérbios 1:7"],["A resposta branda desvia o furor, mas a palavra dura suscita a ira.","Provérbios 15:1"],["A soberba precede a destruição, e a altivez do espírito precede a queda.","Provérbios 16:18"],["E há de ser que, depois disto, derramarei o meu Espírito sobre toda a carne.","Joel 2:28"],["Se tiverdes fé como um grão de mostarda direis a este monte: Passa daqui para acolá, e ele há de passar.","Mateus 17:20"],["Não há justo, nem sequer um. Não há quem entenda; não há quem busque a Deus.","Romanos 3:10"],["Não vos enganeis. As más companhias corrompem os bons costumes.","1 Coríntios 15:33"],["Tendo antes de tudo ardente amor uns para com os outros, porque o amor cobre uma multidão de pecados.","1 Pedro 4:8"],["Maior é aquele que está em vós do que aquele que está no mundo.","1 João 4:4"],["Descansa no Senhor, e espera nele.","Salmo 37:7"],["Pai dos órfãos e juiz das viúvas é Deus na sua santa morada.","Salmo 68:5"],["Buscai ao Senhor, e vivei.","Amós 5:6"],["O Senhor é um Deus zeloso e vingador; o Senhor é vingador e cheio de indignação.","Naum 1:2"],["Seja, porém, o vosso falar: Sim, sim; não, não; pois o que passa daí, vem do Maligno.","Mateus 5:37"],["E até mesmo os cabelos da vossa cabeça estão todos contados.","Mateus 10:30"],["A pedra que os edificadores rejeitaram, essa foi posta como pedra angular.","Salmo 118:22"],["Muita paz têm os que amam a tua lei, e não há nada que os faça tropeçar.","Salmo 119:165"],["Muitos são chamados, mas poucos escolhidos.","Mateus 22:14"],["Pois, quem quer amar a vida, e ver os dias bons, refreie a sua língua do mal.","1 Pedro 3:10"],["Porque já é tempo que comece o julgamento pela casa de Deus.","1 Pedro 4:17"],["Desde agora, a coroa da justiça me está guardada, a qual o Senhor, justo juiz, me dará naquele dia.","2 Timóteo 4:8"],["Lembrai-vos dos vossos guias, os quais vos falaram a palavra de Deus.","Hebreus 13:7"],["Vede que não rejeiteis ao que fala.","Hebreus 12:25"],["Sucederá qualquer mal à cidade, sem que o Senhor o tenha feito?","Amós 3:6"],["Naquele dia tornarei a levantar o tabernáculo de Davi, que está caído.","Amós 9:11"],["Mestre, trabalhamos a noite toda, e nada apanhamos; mas, sobre tua palavra, lançarei as redes.","Lucas 5:5"],["Eu não vim chamar justos, mas pecadores, ao arrependimento.","Lucas 5:32"],["Daquele a quem muito é dado, muito se lhe requererá.","Lucas 12:48"],["Levantai, ó portas, as vossas cabeças; levantai-vos, ó entradas eternas, e entrará o Rei da Glória.","Salmo 24:7"],["Faze-me saber os teus caminhos, Senhor; ensina-me as tuas veredas.","Salmo 25:4"],["Creio que hei de ver a bondade do Senhor na terra dos viventes.","Salmo 27:13"],["Tu és o meu esconderijo; preservas-me da angústia; de alegres cânticos de livramento me cercas.","Salmo 32:7"],["Mais vale o pouco que o justo tem, do que as riquezas de muitos ímpios.","Salmo 37:16"],["Cantarei perpetuamente as misericórdias do Senhor; com a minha boca proclamarei a tua fidelidade de geração em geração.","Salmo 89:1"],["Bem-aventurado o povo que conhece o som festivo, que anda, ó Senhor, na luz da tua face.","Salmo 89:15"],["Direi do Senhor: Ele é o meu refúgio e a minha fortaleza, o meu Deus, em quem confio.","Salmo 91:2"],["Dizei entre as nações: O Senhor reina!","Salmo 96:10"],["Bendizei ao Senhor, vós anjos seus, poderosos em força, que cumpris as suas ordens!","Salmo 103:20"]],"pl":[["Wszystko staranie wasze wrzuciwszy na niego, gdyż on ma pieczę o was.","1 Piotra 5:7"],["Na paszach zielonych postawił mię; a do wód cichych prowadzi mię.","Psalm 23:2"],["Niebiosa opowiadają chwałę Bożą.","Psalm 19:1"],["Nie bój się! bom Ja z tobą. Nie lękaj się! bom Ja Bogiem twoim.","Izajasza 41:10"],["Którzy oczekują Pana, nabywają nowej siły.","Izajasza 40:31"],["I dam wam serce nowe, a ducha nowego dam do wnętrzności waszych.","Ezechiela 36:26"],["Ale ci, którzy innych nauczają, świecić się będą jako światłość na niebie.","Daniela 12:3"],["Błogosławieni ubodzy w duchu; albowiem ich jest królestwo niebieskie.","Mateusza 5:3"],["Wy jesteście światłość świata.","Mateusza 5:14"],["Nie możecie Bogu służyć i mamonie.","Mateusza 6:24"],["Idąc tedy, nauczajcie wszystkie narody.","Mateusza 28:19"],["Wszystko jest możno wierzącemu.","Marka 9:23"],["Iż się wam dziś narodził zbawiciel, który jest Chrystus Pan, w mieście Dawidowem.","Łukasza 2:11"],["Albowiem tąż miarą, którą mierzycie, będzie wam zaś obmierzono.","Łukasza 6:38"],["Musicie się znowu narodzić.","Jana 3:7"],["Jam jest ona winna macica prawdziwa, a Ojciec mój jestci winiarzem.","Jana 15:1"],["A nade wszystko miejcie uprzejmą miłość jedni ku drugim.","1 Piotra 4:8"],["A nie przypodobywajcie się temu światu, ale się przemieńcie przez odnowienie umysłu waszego.","Rzymian 12:2"],["Żyję już nie ja, lecz żyje we mnie Chrystus.","Galacjan 2:20"],["Albowiem mnie życiem jest Chrystus, a umrzeć zysk.","Filipian 1:21"],["I wejrzał Pan na Abla i na ofiarę jego. Ale na Kaina i na ofiarę jego nie wejrzał.","1 Mojżeszowa 4:4"],["Moc moja i chwała moja Pan, bo mi się stał zbawieniem.","2 Mojżeszowa 15:2"],["Bojaźń Pańska jest początkiem umiejętności.","Przypowieści 1:7"],["Odpowiedź łagodna uśmierza gniew; ale słowa przykre wzruszają popędliwość.","Przypowieści 15:1"],["Przed zginieniem przychodzi pycha, a przed upadkiem wyniosłość ducha.","Przypowieści 16:18"],["A potem stanie się, iż wyleję ducha mego na wszelkie ciało.","Joela 2:28"],["Jeźlibyście, mając wiarę jako ziarno gorczyczne, rzekli tej górze: Przenieś się stąd na ono miejsce, tedy się przeniesie.","Mateusza 17:20"],["Nie masz sprawiedliwego ani jednego; nie masz rozumnego i nie masz, kto by szukał Boga.","Rzymian 3:10"],["Nie błądźcież; złe rozmowy psują dobre obyczaje.","1 Koryntian 15:33"],["A nade wszystko miejcie uprzejmą miłość jedni ku drugim; albowiem miłość zakryje mnóstwo grzechów.","1 Piotra 4:8"],["Większy jest ten, który w was jest, niż ten, który jest na świecie.","1 Jana 4:4"],["Poddaj się Panu, a oczekuj go.","Psalm 37:7"],["Ojciec sierot i sędzia wdów jest Bóg w przybytku świętym swoim.","Psalm 68:5"],["Szukajcie Pana, a żyć będziecie.","Amosa 5:6"],["Pan jest Bóg zapalczywy i mściwy; mściwy jest Pan a gniewliwy.","Nahuma 1:2"],["Ale mowa wasza niech będzie: Tak, tak; nie, nie; a co więcej nadto jest, to od złego jest.","Mateusza 5:37"],["Nawet i włosy wszystkie na głowie waszej policzone są.","Mateusza 10:30"],["Kamień, którzy odrzucili budujący, uczyniony jest głową węgielną.","Psalm 118:22"],["Pokój wielki dajesz tym, którzy miłują zakon twój, a nie doznawają żadnego obrażenia.","Psalm 119:165"],["Wiele jest wezwanych, ale mało wybranych.","Mateusza 22:14"],["Albowiem kto chce żywot miłować i oglądać dni dobre, niech pohamuje języka swego od złego.","1 Piotra 3:10"],["Albowiem czas jest, aby się sąd począł od domu Bożego.","1 Piotra 4:17"],["Zatem odłożona mi jest korona sprawiedliwości, którą mi odda w on dzień Pan, sędzia sprawiedliwy.","2 Tymoteusza 4:8"],["Pamiętajcie na wodzów waszych, którzy wam mówili słowo Boże.","Hebrajczyków 13:7"],["Patrzajcież, abyście nie gardzili tym, który mówi.","Hebrajczyków 12:25"],["Izali jest w mieście co złego, którego by Pan nie uczynił?","Amosa 3:6"],["Dnia onego wystawię upadły przybytek Dawidowy.","Amosa 9:11"],["Mistrzu! przez całą noc robiąc, niceśmy nie pojmali, wszakże na słowo twoje zapuszczę sieć.","Łukasza 5:5"],["Nie przyszedłem wzywać sprawiedliwych, ale grzesznych do pokuty.","Łukasza 5:32"],["Od każdego, komu wiele dano, wiele się od niego upominać będą.","Łukasza 12:48"],["Podnieścież, o bramy! wierzchy wasze; podnieście się, wy bramy wieczne! aby wszedł król chwały!","Psalm 24:7"],["Panie! daj mi poznać drogi twe, ścieżek twoich naucz mię.","Psalm 25:4"],["Wierzę, że będę oglądał dobroć Pańską w ziemi żyjących.","Psalm 27:13"],["Tyś jest ucieczką moją; od uciśnienia zachowasz mię, i piosnkami radosnego wybawienia uraczysz mię.","Psalm 32:7"],["Lepsza jest trocha sprawiedliwego, niż wielkie bogactwa wielu niepobożnych.","Psalm 37:16"],["Będę śpiewał na wieki miłosierdzia Pańskie; od narodu do narodu będę opowiadał usty moimi prawdę twoję.","Psalm 89:1"],["Błogosławiony lud, który zna dźwięk twój; Panie! w światłości oblicza twego chodzić będą.","Psalm 89:15"],["Rzecze Panu: Nadzieja moja i zamek mój, Bóg mój, w nim nadzieję mieć będę.","Psalm 91:2"],["Powiadajcie między poganami: Pan króluje!","Psalm 96:10"],["Błogosławcież Panu Aniołowie jego mocni w sile, którzy czynicie rozkazania jego.","Psalm 103:20"]],"cs":[["Všelikou péči vaši uvrhouce na něj. Nebo onť má péči o vás.","1 Petr 5:7"],["Na pastvách zelených pase mne, k vodám tichým mne přivodí.","Žalm 23:2"],["Nebesa vypravují slávu Boha silného...","Žalm 19:2"],["Nebojž se, nebo jsem já s tebou; nestrachujž se, nebo já jsem Bůh tvůj.","Izaiáš 41:10"],["Ale ti, jenž očekávají na Hospodina...","Izaiáš 40:31"],["A dám vám srdce nové, a ducha nového dám do vnitřností vašich...","Ezechiel 36:26"],["Ale ti, kteříž jiné vyučují, stkvíti se budou jako blesk oblohy...","Daniel 12:3"],["Blahoslavení chudí duchem, nebo jejich jest království nebeské.","Matouš 5:3"],["Vy jste světlo světa.","Matouš 5:14"],["Nemůžte Bohu sloužiti i mamoně.","Matouš 6:24"],["Protož jdouce, učte všecky národy...","Matouš 28:19"],["Můžeš-li tomu věřiti; všeckoť jest možné věřícímu.","Marek 9:23"],["Nebo narodil se vám dnes Spasitel, jenž jest Kristus Pán, v městě Davidově.","Lukáš 2:11"],["Touž zajisté měrou, kterouž měříte, bude vám odměřeno.","Lukáš 6:38"],["Musíte se znovu zroditi.","Jan 3:7"],["Já jsem ten vinný kmen pravý, a Otec můj vinař jest","Jan 15:1"],["A protož buďte středmí a bedliví k modlitbám.","1 Petr 4:8"],["A nepřipodobňujte se světu tomuto, ale proměňtež se obnovením mysli vaší...","Římanům 12:2"],["Živť jsem pak již ne já, ale živ jest ve mně Kristus.","Galatským 2:20"],["Mně zajisté Kristus i v životě i v smrti ziskem jest.","Filipským 1:21"],["I vzhlédl Hospodin na Abele a na obět jeho. Na Kaina pak a na obět jeho nevzhlédl.","Genesis 4:4-5"],["Síla má a píseň jest Hospodin, nebo vysvobodil mne. Onť jest Bůh můj silný...","Exodus 15:2"],["Bázeň Hospodinova jest počátek umění...","Přísloví 1:7"],["Odpověd měkká odvracuje hněv, ale řeč zpurná vzbuzuje prchlivost.","Přísloví 15:1"],["Před setřením bývá pýcha, a před pádem pozdvižení ducha.","Přísloví 16:18"],["I stane se potom, že vyleji Ducha svého na všeliké tělo...","Jóel 2:28"],["Amen zajisté pravím vám: Budete-li míti víru, jako jest zrno horčičné, díte hoře této: Jdi odsud tam, a půjde...","Matouš 17:20"],["Že není spravedlivého ani jednoho. Není rozumného, není, kdo by hledal Boha.","Římanům 3:10-11"],["Nedejte se svoditi. Porušujíť dobré obyčeje zlá rozmlouvání.","1 Korintským 15:33"],["A protož buďte středmí a bedliví k modlitbám. Přede vším pak lásku jedni k druhým opravdovou mějte; nebo láska přikryje množství hříchů.","1 Petr 4:8"],["Nebo většíť jest ten, kterýž jest v vás, nežli ten, kterýž jest v světě.","1 Jan 4:4"],["Mlčelivě se měj k Hospodinu, a očekávej na něj pečlivě.","Žalm 37:7"],["Otec jest sirotků a ochránce vdov, Bůh v příbytku svatém svém.","Žalm 68:6"],["Hledejte Hospodina, (a živi buďte...","Ámos 5:6"],["Hospodin jest Bůh horlivý a mstitel, mstitel jestiť Hospodin, a zůřivý.","Nahum 1:2"],["Ale buď řeč vaše: Jistě, jistě; nikoli, nikoli. Což pak nad to více jest, to od toho zlého jest.","Matouš 5:37"],["Vaši pak i vlasové na hlavě všickni sečteni jsou.","Matouš 10:30"],["Kámen, kterýž zavrhli stavitelé, učiněn jest v hlavu úhelní.","Žalm 118:22"],["Pokoj mnohý těm, kteříž milují zákon tvůj, a nemají žádné urážky.","Žalm 119:165"],["Nebo mnoho jest povolaných, ale málo vyvolených.","Matouš 22:14"],["Nebo kdož chce milovati život, a viděti dny dobré, zkrocujž jazyk svůj od zlého...","1 Petr 3:10"],["Neboť jest čas, aby se začal soud od domu Božího.","1 Petr 4:17"],["Již za tím odložena jest mi koruna spravedlnosti, kterouž dá mi v onen den Pán, ten spravedlivý soudce...","2 Timoteovi 4:8"],["Zpomínejte na vůdce vaše, kteříž vám mluvili slovo Boží...","Židům 13:7"],["Viztež, abyste neodpírali mluvícím. Nebo poněvadž onino neušli pomsty...","Židům 12:25"],["Zdaž když se má státi v městě co zlého, Hospodin toho známa nečiní?","Ámos 3:6"],["V ten den zdvihnu stánek Davidův, kterýž klesá...","Ámos 9:11"],["Řekl jemu: Mistře, přes celou noc pracovavše, nic jsme nepopadli, ale k slovu tvému rozestru sít.","Lukáš 5:5"],["Nepřišelť jsem volati spravedlivých, ale hříšných ku pokání.","Lukáš 5:32"],["Každému pak, komuž jest mnoho dáno, mnoho bude od něho požádáno...","Lukáš 12:48"],["Pozdvihnětež, ó brány, svrchků svých, pozdvihnětež se vrata věčná, aby vjíti mohl král slávy.","Žalm 24:7"],["Cesty své, Hospodine, uveď mi v známost, a stezkám svým vyuč mne.","Žalm 25:4"],["Bychť nevěřil, že užívati budu dobroty Hospodinovy v zemi živých, nikoli bych neostál.","Žalm 27:13"],["Ty jsi skrýše má, od ssoužení zachováš mne, a plésáním vítězným obdaříš. Sélah.","Žalm 32:7"],["Lepší jest málo, což má spravedlivý, než veliká bohatství bezbožníků mnohých.","Žalm 37:16"],["O milosrdenstvích Hospodinových na věky zpívati budu, od národu do pronárodu zvěstovati budu pravdu tvou ústy svými.","Žalm 89:2"],["Blahoslavený lid, kterýž zná zvuk tvůj; tiť, Hospodine, v světle oblíčeje tvého choditi budou.","Žalm 89:16"],["Dím Hospodinu: Útočiště mé a hrad můj, Bůh můj, v němž naději skládati budu.","Žalm 91:2"],["Rcete mezi pohany: Hospodin kraluje...","Žalm 96:10"],["Dobrořečte Hospodinu andělé jeho, kteříž jste mocní v síle, a činíte slovo jeho...","Žalm 103:20"]],"ro":[["Şi aruncaţi asupra Lui toate îngrijorările voastre, căci El însuşi îngrijeşte de voi.","1 Petru 5:7"],["El mă paşte în păşuni verzi şi mă duce la ape de odihnă...","Psalmii 23:2"],["Cerurile spun slava lui Dumnezeu...","Psalmii 19:1"],["Nu te teme, căci Eu sunt cu tine; nu te uita cu îngrijorare, căci Eu sunt Dumnezeul tău...","Isaia 41:10"],["Dar cei ce se încred în Domnul îşi înnoiesc puterea...","Isaia 40:31"],["Vă voi da o inimă nouă şi voi pune în voi un duh nou...","Ezechiel 36:26"],["Cei înţelepţi vor străluci ca strălucirea cerului...","Daniel 12:3"],["„Ferice de cei săraci în duh, căci a lor este Împărăţia cerurilor!","Matei 5:3"],["Voi sunteţi lumina lumii.","Matei 5:14"],["Nu puteţi sluji lui Dumnezeu şi lui Mamona.","Matei 6:24"],["Duceţi-vă şi faceţi ucenici din toate neamurile...","Matei 28:19"],["Toate lucrurile sunt cu putinţă celui ce crede!”","Marcu 9:23"],["Astăzi, în cetatea lui David, vi S-a născut un Mântuitor, care este Hristos, Domnul.","Luca 2:11"],["Căci cu ce măsură veţi măsura, cu aceea vi se va măsura.”","Luca 6:38"],["Trebuie să vă naşteţi din nou.”","Ioan 3:7"],["Eu sunt adevărata Viţă, şi Tatăl Meu este Vierul.","Ioan 15:1"],["Mai presus de toate, să aveţi o dragoste fierbinte unii pentru alţii...","1 Petru 4:8"],["Să nu vă potriviţi chipului veacului acestuia, ci să vă prefaceţi, prin înnoirea minţii voastre...","Romani 12:2"],["Şi trăiesc… dar nu mai trăiesc eu, ci Hristos trăieşte în mine.","Galateni 2:20"],["Căci pentru mine a trăi este Hristos, şi a muri este un câştig.","Filipeni 1:21"],["Domnul a privit cu plăcere spre Abel şi spre jertfa lui; dar spre Cain şi spre jertfa lui n-a privit cu plăcere.","Geneza 4:4-5"],["Domnul este tăria mea şi temeiul cântărilor mele de laudă: El m-a scăpat.","Exodul 15:2"],["Frica Domnului este începutul ştiinţei...","Proverbe 1:7"],["Un răspuns blând potoleşte mânia, dar o vorbă aspră aţâţă mânia.","Proverbe 15:1"],["Mândria merge înaintea pieirii, şi trufia merge înaintea căderii....","Proverbe 16:18"],["După aceea voi turna Duhul Meu peste orice făptură...","Ioel 2:28"],["Adevărat vă spun că, dacă aţi avea credinţă cât un grăunte de muştar, aţi zice muntelui acestuia: „Mută-te de aici acolo”, şi s-ar muta...","Matei 17:20"],["Nu este niciun om neprihănit, niciunul măcar. Nu este niciunul care să aibă pricepere. Nu este niciunul care să caute cu tot dinadinsul pe Dumnezeu.","Romani 3:10-11"],["Nu vă înşelaţi: „Tovărăşiile rele strică obiceiurile bune”.","1 Corinteni 15:33"],["Mai presus de toate, să aveţi o dragoste fierbinte unii pentru alţii, căci dragostea acoperă o sumedenie de păcate.","1 Petru 4:8"],["Pentru că Cel ce este în voi este mai mare decât cel ce este în lume.","1 Ioan 4:4"],["Taci înaintea Domnului şi nădăjduieşte în El.","Psalmii 37:7"],["El este tatăl orfanilor, apărătorul văduvelor, El, Dumnezeu, care locuieşte în Locaşul Lui cel Sfânt.","Psalmii 68:5"],["Căutaţi pe Domnul, şi veţi trăi!","Amos 5:6"],["Domnul este un Dumnezeu gelos şi răzbunător; Domnul Se răzbună şi este plin de mânie...","Naum 1:2"],["Felul vostru de vorbire să fie: „Da, da; nu, nu”; ce trece peste aceste cuvinte vine de la cel rău.","Matei 5:37"],["Cât despre voi, până şi perii din cap, toţi vă sunt număraţi.","Matei 10:30"],["Piatra pe care au lepădat-o zidarii a ajuns să fie pusă în capul unghiului clădirii.","Psalmii 118:22"],["Multă pace au cei ce iubesc Legea Ta şi nu li se întâmplă nicio nenorocire.","Psalmii 119:165"],["Căci mulţi sunt chemaţi, dar puţini sunt aleşi.”","Matei 22:14"],["Căci cine iubeşte viaţa şi vrea să vadă zile bune să-şi înfrâneze limba de la...","1 Petru 3:10"],["Căci suntem în clipa când judecata stă să înceapă de la Casa lui Dumnezeu.","1 Petru 4:17"],["De acum mă aşteaptă cununa neprihănirii, pe care mi-o va da în „ziua aceea” Domnul, Judecătorul cel drept.","2 Timotei 4:8"],["Aduceţi-vă aminte de mai marii voştri, care v-au vestit Cuvântul lui Dumnezeu...","Evrei 13:7"],["Luaţi seama ca nu cumva să nu voiţi să ascultaţi pe Cel ce vă vorbeşte!","Evrei 12:25"],["Sau se întâmplă o nenorocire într-o cetate fără s-o fi făcut Domnul?","Amos 3:6"],["În vremea aceea voi ridica din căderea lui cortul lui David...","Amos 9:11"],["Învăţătorule, toată noaptea ne-am trudit şi n-am prins nimic; dar, la cuvântul Tău, voi arunca mrejele!”","Luca 5:5"],["N-am venit să chem la pocăinţă pe cei neprihăniţi, ci pe cei păcătoşi.”","Luca 5:32"],["Cui i s-a dat mult, i se va cere mult...","Luca 12:48"],["Porţi, ridicaţi-vă capetele; ridicaţi-vă, porţi veşnice, ca să intre Împăratul slavei!...","Psalmii 24:7"],["Arată-mi, Doamne, căile Tale şi învaţă-mă cărările Tale.","Psalmii 25:4"],["O! dacă n-aş fi încredinţat că voi vedea bunătatea Domnului pe pământul celor vii!…","Psalmii 27:13"],["Tu eşti ocrotirea mea, Tu mă scoţi din necaz, Tu mă înconjori cu cântări de izbăvire. (Oprire)","Psalmii 32:7"],["Mai mult face puţinul celui neprihănit decât belşugul multor răi.","Psalmii 37:16"],["Voi cânta totdeauna îndurările Domnului, voi spune din neam în neam, cu gura mea, credincioşia Ta.","Psalmii 89:1"],["Ferice de poporul care cunoaşte sunetul trâmbiţei, care umblă în lumina feţei Tale, Doamne!","Psalmii 89:15"],["Zice despre Domnul: „El este locul meu de scăpare şi cetăţuia mea, Dumnezeul meu în care mă încred!”","Psalmii 91:2"],["Spuneţi printre neamuri: „Domnul împărăţeşte!","Psalmii 96:10"],["Binecuvântaţi pe Domnul, îngerii Lui, care sunteţi tari în putere...","Psalmii 103:20"]],"hu":[["Minden gondotokat ő reá vessétek, mert néki gondja van reátok.","1 Péter 5:7"],["Fűves legelőkön nyugtat engem, és csendes vizekhez terelget engem.","Zsoltárok 23:2"],["Az egek beszélik Isten dicsőségét...","Zsoltárok 19:2"],["Ne félj, mert én veled vagyok; ne csüggedj...","Ézsaiás 41:10"],["De a kik az Úrban bíznak, erejök megújul...","Ézsaiás 40:31"],["És adok néktek új szívet, és új lelket adok belétek...","Ezékiel 36:26"],["Az értelmesek pedig fénylenek, mint az égnek fényessége...","Dániel 12:3"],["Boldogok a lelki szegények: mert övék a mennyeknek országa.","Máté 5:3"],["Ti vagytok a világ világossága.","Máté 5:14"],["Nem szolgálhattok Istennek és a Mammonnak.","Máté 6:24"],["Elmenvén azért, tegyetek tanítványokká minden népeket...","Máté 28:19"],["Minden lehetséges a hívőnek.","Márk 9:23"],["Mert született néktek ma a Megtartó, ki az Úr Krisztus, a Dávid városában.","Lukács 2:11"],["Mert azzal a mértékkel mérnek néktek, a melylyel ti mértek.","Lukács 6:38"],["Szükség néktek újonnan születnetek.","János 3:7"],["Én vagyok az igazi szőlőtő, és az én Atyám a szőlőműves.","János 15:1"],["Mindenek előtt pedig legyetek hajlandók az egymás iránti szeretetre...","1 Péter 4:8"],["És ne szabjátok magatokat e világhoz, hanem változzatok el a ti elméteknek megújulása által...","Róma 12:2"],["Élek pedig többé nem én, hanem él bennem a Krisztus...","Galata 2:20"],["Mert nékem az élet Krisztus, és a meghalás nyereség.","Filippi 1:21"],["És tekinte az Úr Ábelre és az ő ajándékára. Kainra pedig és az ő ajándékára nem tekinte...","1 Mózes 4:4-5"],["Erősségem az Úr és énekem, szabadítómmá lőn nekem...","2 Mózes 15:2"],["Az Úrnak félelme feje a bölcseségnek...","Példabeszédek 1:7"],["Az engedelmes felelet elfordítja a harag felgerjedését; a megbántó beszéd pedig támaszt haragot.","Példabeszédek 15:1"],["A megromlás előtt kevélység jár, és az eset előtt felfuvalkodottság.","Példabeszédek 16:18"],["És lészen azután, hogy kiöntöm lelkemet minden testre...","Jóel 2:28"],["Mert bizony mondom néktek: Ha akkora hitetek volna, mint a mustármag, azt mondanátok ennek a hegynek: Menj innen amoda, és elmenne...","Máté 17:20"],["Hogy nincsen csak egy igaz is; Nincs, a ki megértse, nincs, a ki keresse az Istent.","Róma 3:10-11"],["Ne tévelyegjetek. Jó erkölcsöt megrontanak gonosz társaságok.","1 Korinthus 15:33"],["Mindenek előtt pedig legyetek hajlandók az egymás iránti szeretetre; mert a szeretet sok vétket elfedez.","1 Péter 4:8"],["A ki bennetek van, mint az, a ki e világban van.","1 János 4:4"],["Csillapodjál le az Úrban és várjad őt...","Zsoltárok 37:7"],["Árváknak atyja, özvegyeknek bírája az Isten az ő szentséges hajlékában.","Zsoltárok 68:6"],["Keressétek az Urat, és éltek...","Ámósz 5:6"],["Buzgón szerető és bosszúálló Isten az Úr, bosszúálló az Úr, és telve haraggal...","Náhum 1:2"],["Hanem legyen a ti beszédetek: Úgy úgy; nem nem; a mi pedig ezeken felül vagyon, a gonosztól vagyon.","Máté 5:37"],["Néktek pedig még a fejetek hajszálai is mind számon vannak.","Máté 10:30"],["A kő a melyet az építők megvetettek, szegeletkővé lett!","Zsoltárok 118:22"],["A te törvényed kedvelőinek nagy békességök van, és nincs bántódásuk.","Zsoltárok 119:165"],["Mert sokan vannak a hivatalosok, de kevesen a választottak.","Máté 22:14"],["Mert a ki akarja az életet szeretni, jó napokat látni, tiltsa meg nyelvét a gonosztól...","1 Péter 3:10"],["Mert itt az ideje, hogy elkezdődjék az ítélet az Istennek házán...","1 Péter 4:17"],["Végezetre eltétetett nékem az igazság koronája, melyet megád nékem az Úr ama napon, az igaz Bíró...","2 Timóteus 4:8"],["Emlékezzetek meg a ti előljáróitokról, a kik szólották néktek az Isten beszédét...","Zsidók 13:7"],["Vigyázzatok, meg ne vessétek azt, a ki szól...","Zsidók 12:25"],["Vajjon lehet-é baj a városban, a mit nem az Úr szerezne?","Ámósz 3:6"],["Azon a napon felemelem a Dávid leomlott sátorát...","Ámósz 9:11"],["Mester, jóllehet az egész éjszaka fáradtunk, még sem fogtunk semmit: mindazáltal a te parancsolatodra levetem a hálót.","Lukács 5:5"],["Nem azért jöttem, hogy az igazakat hívjam, hanem a bűnösöket a megtérésre.","Lukács 5:32"],["És valakinek sokat adtak, sokat követelnek tőle...","Lukács 12:48"],["Ti kapuk, emeljétek fel fejeiteket, és emelkedjetek fel ti örökkévaló ajtók; hadd menjen be a dicsőség királya.","Zsoltárok 24:7"],["Útjaidat, Uram, ismertesd meg velem, ösvényeidre taníts meg engem.","Zsoltárok 25:4"],["Bizony hiszem, hogy meglátom az Úr jóságát az élőknek földén!","Zsoltárok 27:13"],["Te vagy oltalmam, te mentesz meg veszedelemtől; végy körül engem a szabadulás örömével! Szela.","Zsoltárok 32:7"],["Jobb a kevés az igaznak, mint a sok gonosznak az ő gazdagsága.","Zsoltárok 37:16"],["Az Úrnak kegyelmességét hadd énekeljem örökké! Nemzetségről nemzetségre hirdetem a te hűséges voltodat az én számmal!","Zsoltárok 89:2"],["Boldog nép az, a mely megérti a kürt szavát; a te orczádnak világosságánál jár ez, oh Uram!","Zsoltárok 89:16"],["Azt mondom az Úrnak: Én oltalmam, váram, Istenem ő benne bízom!","Zsoltárok 91:2"],["Mondjátok a népek között: Az Úr uralkodik...","Zsoltárok 96:10"],["Áldjátok az Urat ő angyalai, ti hatalmas erejűek, a kik teljesítitek az ő rendeletét...","Zsoltárok 103:20"]],"nl":[["Werpt al uw bekommernis op Hem, want Hij zorgt voor u.","1 Petrus 5:7"],["Hij doet mij nederliggen in grazige weiden; Hij voert mij zachtjes aan zeer stille wateren.","Psalm 23:2"],["De hemelen vertellen Gods eer...","Psalm 19:2"],["Vrees niet, want Ik ben met u; zijt niet verbaasd, want Ik ben uw God...","Jesaja 41:10"],["Maar dien den HEERE verwachten, zullen de kracht vernieuwen...","Jesaja 40:31"],["En Ik zal u een nieuw hart geven, en zal een nieuwen geest geven in het binnenste van u...","Ezechiël 36:26"],["De leraars nu zullen blinken, als de glans des uitspansels...","Daniël 12:3"],["Zalig zijn de armen van geest; want hunner is het Koninkrijk der hemelen.","Mattheüs 5:3"],["Gij zijt het licht der wereld...","Mattheüs 5:14"],["Gij kunt niet God dienen en den Mammon.","Mattheüs 6:24"],["Gaat dan henen, onderwijst al de volken...","Mattheüs 28:19"],["Alle dingen zijn mogelijk dengene, die gelooft.","Markus 9:23"],["Namelijk dat u heden geboren is de Zaligmaker, welke is Christus, de Heere, in de stad Davids.","Lukas 2:11"],["Want met dezelfde maat, waarmede gijlieden meet, zal ulieden wedergemeten worden.","Lukas 6:38"],["Gijlieden moet wederom geboren worden.","Johannes 3:7"],["Ik ben de ware Wijnstok, en Mijn Vader is de Landman.","Johannes 15:1"],["Maar vooral hebt vurige liefde tot elkander...","1 Petrus 4:8"],["En wordt dezer wereld niet gelijkvormig; maar wordt veranderd door de vernieuwing uws gemoeds...","Romeinen 12:2"],["En ik leef, doch niet meer ik, maar Christus leeft in mij...","Galaten 2:20"],["Want het leven is mij Christus, en het sterven is mij gewin.","Filippenzen 1:21"],["En de HEERE zag Habel en zijn offer aan; Maar Kain en zijn offer zag Hij niet aan.","Genesis 4:4-5"],["De HEERE is mijn Kracht en Lied, en Hij is mij tot een Heil geweest...","Exodus 15:2"],["De vrees des HEEREN is het beginsel der wetenschap...","Spreuken 1:7"],["Een zacht antwoord keert de grimmigheid af; maar een smartend woord doet den toorn oprijzen.","Spreuken 15:1"],["Hovaardigheid is voor de verbreking, en hoogheid des geestes voor den val.","Spreuken 16:18"],["En daarna zal het geschieden, dat Ik Mijn Geest zal uitgieten over alle vlees...","Joël 2:28"],["Zo gij een geloof hadt als een mosterdzaad, gij zoudt tot deze berg zeggen: Ga heen van hier derwaarts, en hij zal heengaan...","Mattheüs 17:20"],["Er is niemand rechtvaardig, ook niet een; Er is niemand, die verstandig is, er is niemand, die God zoekt.","Romeinen 3:10-11"],["Dwaalt niet, kwade samensprekingen verderven goede zeden.","1 Korinthe 15:33"],["Maar vooral hebt vurige liefde tot elkander; want de liefde zal menigte van zonden bedekken.","1 Petrus 4:8"],["Want Hij is meerder, Die in u is, dan die in de wereld is.","1 Johannes 4:4"],["Daleth. Zwijg den HEERE, en verbeid Hem...","Psalm 37:7"],["Hij is een Vader der wezen, en een Rechter der weduwen; God, in de woonstede Zijner heiligheid.","Psalm 68:6"],["Zoekt den HEERE, en leeft...","Amos 5:6"],["Een ijverig God en een wreker is de HEERE, een wreker is de HEERE, en zeer grimmig...","Nahum 1:2"],["Maar laat zijn uw woord ja, ja; neen, neen; wat boven deze is, dat is uit den boze.","Mattheüs 5:37"],["En ook uw haren des hoofds zijn alle geteld.","Mattheüs 10:30"],["De steen, dien de bouwlieden verworpen hadden, is tot een hoofd des hoeks geworden.","Psalm 118:22"],["Die Uw wet beminnen, hebben groten vrede, en zij hebben geen aanstoot.","Psalm 119:165"],["Want velen zijn geroepen, maar weinigen uitverkoren.","Mattheüs 22:14"],["Want wie het leven wil liefhebben, en goede dagen zien, die stille zijn tong van het kwaad...","1 Petrus 3:10"],["Want het is de tijd, dat het oordeel beginne van het huis Gods...","1 Petrus 4:17"],["Voorts is mij weggelegd de kroon der rechtvaardigheid, welke mij de Heere, de rechtvaardige Rechter, in dien dag geven zal...","2 Timotheüs 4:8"],["Gedenkt uwer voorgangeren, die u het Woord Gods gesproken hebben...","Hebreeën 13:7"],["Ziet toe, dat gij Dien, Die spreekt, niet verwerpt...","Hebreeën 12:25"],["Zal er een kwaad in de stad zijn, dat de HEERE niet doet?","Amos 3:6"],["Te dien dage zal Ik de vervallen hut van David weder oprichten...","Amos 9:11"],["Meester, wij hebben den gehelen nacht over gearbeid, en niet gevangen; doch op Uw woord zal ik het net uitwerpen.","Lukas 5:5"],["Ik ben niet gekomen om te roepen rechtvaardigen, maar zondaren tot bekering.","Lukas 5:32"],["En een iegelijk, wien veel gegeven is, van dien zal veel geeist worden...","Lukas 12:48"],["Heft uw hoofden op, gij poorten, en verheft u, gij eeuwige deuren, opdat de Koning der ere inga!","Psalm 24:7"],["Daleth. HEERE! maak mij Uw wegen bekend, leer mij Uw paden.","Psalm 25:4"],["Zo ik niet had geloofd, dat ik het goede des HEEREN zou zien in het land der levenden, ik ware vergaan.","Psalm 27:13"],["Gij zijt mij een Verberging; Gij behoedt mij voor benauwdheid; Gij omringt mij met vrolijke gezangen van bevrijding. Sela.","Psalm 32:7"],["Teth. Het weinige, dat de rechtvaardige heeft, is beter dan de overvloed veler goddelozen.","Psalm 37:16"],["Ik zal de goedertierenheid des HEEREN eeuwiglijk zingen; ik zal Uw waarheid met mijn mond bekend maken, van geslacht tot geslacht.","Psalm 89:2"],["Welgelukzalig is het volk, hetwelk het geklank kent; o HEERE! zij zullen in het licht Uws aanschijns wandelen.","Psalm 89:16"],["Ik zal tot den HEERE zeggen: Mijn Toevlucht en mijn Burg! mijn God, op Welken ik vertrouw!","Psalm 91:2"],["Zegt onder de heidenen: De HEERE regeert...","Psalm 96:10"],["Looft den HEERE, Zijn engelen! gij krachtige helden, die Zijn woord doet...","Psalm 103:20"]]};
